content.query:
// Count of all Arc-enabled SQL Server instances
resources
| where type == "microsoft.azurearcdata/sqlserverinstances"
{ResourceGroup:filters}
| summarize Servers=count()

// Count of all databases across Arc-enabled SQL Server instances
resources
| where type == "microsoft.azurearcdata/sqlserverinstances/databases"
{ResourceGroup:filters}
| count

// Count of protected instances by Azure Defender
resources
| where type == "microsoft.azurearcdata/sqlserverinstances"
{ResourceGroup:filters}
| where tostring(properties['azureDefenderStatus']) == "Protected"
| count

// Count of encrypted databases
resources
| where type == "microsoft.azurearcdata/sqlserverinstances/databases"
{ResourceGroup:filters}
| where tostring(properties['databaseOptions'].isEncrypted) == "true"
| count

// SQL Server editions distribution
resources
| where type == "microsoft.azurearcdata/sqlserverinstances"
{ResourceGroup:filters}
| summarize Count=count() by Edition=tostring(properties['edition'])
| order by Count desc

// Database compatibility levels
resources
| where type == "microsoft.azurearcdata/sqlserverinstances/databases"
{ResourceGroup:filters}
| summarize Count=count() by CompatibilityLevel=tostring(properties['compatibilityLevel'])
| order by Count desc

// Azure Defender for SQL status
resources
| where type == "microsoft.azurearcdata/sqlserverinstances"
{ResourceGroup:filters}
| summarize Count=count() by DefenderStatus=iff(tostring(properties['azureDefenderStatus'])=="Unknown", "Not Protected", tostring(properties['azureDefenderStatus']))
| order by Count desc

// Database encryption status
resources
| where type == "microsoft.azurearcdata/sqlserverinstances/databases"
{ResourceGroup:filters}
| summarize Count=count() by Encrypted=iif(tostring(properties['databaseOptions'].isEncrypted)=="false", "No", "Yes")

// Extension license type distribution
resources
| where type == "microsoft.hybridcompute/machines/extensions"
| where properties.type in ("WindowsAgent.SqlServer", "LinuxAgent.SqlServer")
{ResourceGroup:filters}
| summarize Count=count() by LicenseType=tostring(properties.settings.LicenseType)
